import * as React from 'react';
import { createPortal } from 'react-dom';
import { mergeRefs } from '../../../util/reactUtil.ts';
import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';

import { type BannerVariant, Banner } from '../../containers/Banner/Banner.tsx';
import { TopLayerContext, useActiveModalDialog } from '../../util/overlays/TopLayerManager.tsx';

import { type ToastId, type ToastDescriptor, type ToastOptions, type ToastStorage, ToastStore } from './ToastStore.ts';

import cl from './ToastProvider.module.scss';


export { cl as ToasterClassNames };

export type { ToastDescriptor };

export const createToastNotifier = (toastStore: ToastStore) => {
  const notify = (toast: ToastDescriptor) => {
    // If a toast with the same dedupeKey is already active, do not create another one.
    if (toastStore.hasActiveDedupeKey(toast)) { return; }
    const toastId = toastStore.uniqueId();
    toastStore.announceToast(toastId, toast);
  };
  const notifyVariant = (
    variant: BannerVariant,
    toast: string | Omit<ToastDescriptor, 'variant'>,
    options?: undefined | ToastOptions,
  ) => {
    const descriptor: ToastDescriptor = typeof toast === 'string'
      ? { variant, message: toast, options }
      : { ...toast, variant, options: { ...toast.options, ...(options ?? {}) } };
    notify(descriptor);
  };
  return Object.assign(notify, {
    info: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
      notifyVariant('info', toast, options),
    warning: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
      notifyVariant('warning', toast, options),
    error: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
      notifyVariant('error', toast, options),
    success: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
      notifyVariant('success', toast, options),
    dismiss: (toastId: ToastId) => {
      toastStore.dismissToast(toastId);
    },
    dismissAll: () => {
      toastStore.dismissAllToasts();
    },
  });
};

export const Toast = (props: React.ComponentProps<typeof Banner>) => {
  return (
    <Banner
      trimmed
      compact={false}
      showCloseAction
      {...props}
      className={cx(cl['bk-toast'], props.className)}
    />
  )
};

export const ToastCopyAction = ({ toast }: { toast: ToastDescriptor }) => {
  const defaultLabel = 'Copy';
  const [label, setLabel] = React.useState(defaultLabel);

  const handleCopy = React.useCallback(async (message: string) => {
    try {
      // Idea: use `write()` with HTML mime type to copy arbitrary content? Could get the `innerHTML` through a ref.
      if (navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(message);
      }

      setLabel('Copied!');
    } catch (error: unknown) {
      setLabel('Error: unable to copy');
    }
  }, []);

  const message = toast.message;

  // Currently don't support copying unless the message is a string
  if (typeof message !== 'string') { return null; }

  return (
    <Banner.ActionIcon
      icon="copy"
      label={label}
      onPress={() => handleCopy(message)} // Note: careful to return the promise here to `onPress`
      onMouseLeave={() => {
        // Reset the label after exit animation had a chance to complete
        window.setTimeout(() => { setLabel(defaultLabel); }, 500);
      }}
    />
  );
};

export type ToasterProps = React.PropsWithChildren<ComponentProps<'section'>>;
/**
 * Renders any current toast notifications.
 */
export const Toaster = (props: ToasterProps) => {
  const { ...propsRest } = props;
  const { toastStore } = useToastContext();

  // Cache the toasts we read from the store.
  // Note: initialize function must read the toasts synchronously from the store, we cannot wait until the first
  // `subscribe()` kicks in, because then we spend one render cycle without state (which causes flickering).
  const [toasts, setToasts] = React.useState<ToastStorage>(() => toastStore.toasts());

  React.useEffect(() => {
    return toastStore.subscribe(toasts => {
      // FIXME: it would be nice to do this in a view transition so that things like toast shifting animates properly.
      // However view transitions cause some issues, e.g. click events don't fire while the transition is happening.
      //startViewTransition(() => {
        setToasts(toasts);
      //});
    });
  }, [toastStore]);

  // Pause auto-close when the page is not currently visible by the user
  React.useEffect(() => {
    const controller = new AbortController();

    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        toastStore.onPageVisible();
      } else {
        toastStore.onPageHide();
      }
    }, { signal: controller.signal });

    return () => { controller.abort(); };
  }, [toastStore]);

  const containerRef = React.useRef<null | React.ComponentRef<'section'>>(null);
  const openPopover = React.useCallback((container: null | HTMLElement) => {
    if (container && container.isConnected) {
      try {
        container.hidePopover();
        container.showPopover();
      } catch (error: unknown) {
        console.error(`Failed to open Toaster`, error);
      }
    }
  }, []);

  // Ref callback to enforce that the Toaster is always rendered as a popover
  const enforcePopoverOpen: React.RefCallback<React.ComponentRef<'section'>> = container => {
    containerRef.current = container;
    openPopover(container);
  };

  const modalDialogContext = React.use(TopLayerContext);
  React.useEffect(() => {
    if (modalDialogContext === null) { throw new Error(`Cannot read ModalDialogContext: missing provider.`); }
    return modalDialogContext.modalDialogStack.subscribe(() => { openPopover(containerRef.current); });
  }, [modalDialogContext, openPopover]);

  return (
    <section
      aria-label="Notifications"
      tabIndex={-1} // Do not include in normal tab order
      aria-live="polite"
      aria-relevant="additions text"
      aria-atomic="false"
      popover="manual"
      {...propsRest}
      ref={mergeRefs(enforcePopoverOpen, propsRest.ref)}
      className={cx(
        'bk',
        cl['bk-toaster'],
        propsRest.className,
      )}
    >
      {Object.entries(toasts).map(([toastKey, { metadata, descriptor: toast }]) => {
        const toastId = toastStore.idFromKey(toastKey);
        return (
          <Toast
            key={toastKey}
            className={cx({
              [cl['bk-toast--skip-entry']]: toastStore.shouldSkipEntryAnimation(toastId),
            })}
            variant={toast.variant}
            title={toast.title}
            hidden={metadata.dismissed}
            actions={
              <ToastCopyAction toast={toast}/>
            }
            onClose={() => {
              toastStore.dismissToast(toastId);
            }}
            // Handle dismiss signals (e.g. clicking or tapping on the toast)
            onClick={event => { event.stopPropagation(); toastStore.dismissToast(toastId); }}
            // Handle interest signals (e.g. hovering over the toast)
            onMouseEnter={event => { event.stopPropagation(); toastStore.pauseAutoClose(toastId); }}
            onTouchStart={event => { event.stopPropagation(); toastStore.pauseAutoClose(toastId); }}
            onMouseLeave={event => { event.stopPropagation(); toastStore.resumeAutoClose(toastId); }}
            onTouchEnd={event => { event.stopPropagation(); toastStore.resumeAutoClose(toastId); }}
          >
            {toast.message}
          </Toast>
        );
      })}
    </section>
  );
};


export type ToastContext = { toastStore: ToastStore, notify: (toast: ToastDescriptor) => void };
export const ToastContext = React.createContext<null | ToastContext>(null);
export const useToastContext = (): ToastContext => {
  const context = React.use(ToastContext);
  if (context === null) { throw new Error(`Missing ToastContext`); }
  return context;
};

// A single global instance, to be used with `<ToastProvider global/>`
export const globalToastStore = new ToastStore();
export const notify = createToastNotifier(globalToastStore);

type ToastProviderProps = React.PropsWithChildren<{ global?: boolean }>;
export const ToastProvider = ({ global = false, children }: ToastProviderProps) => {
  const activeModalDialog = useActiveModalDialog();

  // Note: we need to be careful to not store toasts in `useState()` in this component, otherwise the entire
  // subtree will be rerendered on every change. Use the Observable pattern instead.
  // https://www.fullstory.com/blog/why-fullstory-uses-observables-in-react

  const toastStoreRef = React.useRef<null | ToastStore>(global ? globalToastStore : null);
  const toastStore = toastStoreRef.current ?? new ToastStore(); // Lazy initialization

  const toastContext = React.useMemo(() => ({
    toastStore,
    notify: createToastNotifier(toastStore),
  }), [toastStore]);

  return (
    <ToastContext value={toastContext}>
      {children}
      {/*
      Render the toasts in the top-most modal `<dialog>`, to work around browser limitations where only the `<dialog>`
      element and its descendants are interactive (everything else is inert).
      */}
      {createPortal(<Toaster/>, activeModalDialog?.dialogRef?.current ?? window.document.body)}
    </ToastContext>
  );
};

export const useNotify = () => {
  return useToastContext().notify;
};


--- src/components/overlays/ToastProvider/ToastStore.ts ---
/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import { Timer } from '../../../util/time.ts';
import * as React from 'react';

import { type BannerVariant } from '../../containers/Banner/Banner.tsx';


export type ToastId = string;
export type ToastOptions = {
  autoClose?: undefined | false | number /*ms*/, // Time after which to automatically close the toast
  dedupeKey?: undefined | string, // Optional unique identifier used to deduplicate notifications
};
export type ToastDescriptor = {
  variant: BannerVariant,
  message: React.ReactNode,
  title?: undefined | string,
  options?: undefined | ToastOptions,
};

export type ToastStoreOptions = {
  entryAnimationDelay?: number /*ms*/,
  exitAnimationDelay?: number /*ms*/,
  autoCloseDelay?: number /*ms*/, // Should be higher than `entryAnimationDelay`
};
export type ToastMetadata = {
  openedAt: Date,
  dismissed: boolean,
  autoCloseTimer: null | Timer,
};
export type ToastWithMetadata = { metadata: ToastMetadata, descriptor: ToastDescriptor };
export type ToastStorage = Readonly<Record<ToastId, ToastWithMetadata>>;
export type ToastSubscriber = (this: ToastStore, toasts: ToastStorage) => void;

/**
 * Store for the currently active toasts. Can be subscribed to to get notified when the state changes.
 */
export class ToastStore {
  #options: Required<ToastStoreOptions>;

  #idCounter = 0; // Maintain a count for automatic ID generation
  #toasts: ToastStorage = Object.create(null);
  #subscribers: Set<ToastSubscriber> = new Set();
  #dedupeKeys: Set<string> = new Set(); // Tracks active dedupe keys to prevent showing duplicate notifications.

  constructor(options: ToastStoreOptions = {}) {
    this.#options = {
      entryAnimationDelay: options.entryAnimationDelay ?? 400,
      exitAnimationDelay: options.exitAnimationDelay ?? 200,
      autoCloseDelay: options.autoCloseDelay ?? 8000,
    };
  }

  toasts() { return { ...this.#toasts }; }

  /** Subscribe to updates on the store (observable pattern). Returns a function to unsubscribe. */
  subscribe(subscriber: ToastSubscriber): () => void {
    this.#subscribers.add(subscriber);
    subscriber.call(this, this.#toasts); // Publish the current state
    return () => {
      this.#subscribers.delete(subscriber);
    };
  }

  /** Publish the current state to all subscribers. */
  publish() {
    for (const subscriber of this.#subscribers) {
      subscriber.call(this, this.#toasts);
    }
  }

  uniqueId(): ToastId {
    const id = this.#idCounter++;
    if (this.#idCounter >= Number.MAX_SAFE_INTEGER - 1) {
      this.#idCounter = 0;
    }
    return String(id);
  }

  // Generate an object key from the given ID. We prefix the ID, to make sure the key is not number-like in order
  // to enforce that the object entries are ordered by insertion.
  keyFromId(toastId: ToastId) {
    return `toast-${toastId}`;
  }
  idFromKey(toastKey: string): ToastId {
    return toastKey.replace(/^toast-/, '');
  }

  getToastById(toastId: ToastId): null | ToastWithMetadata {
    const toastKey = this.keyFromId(toastId);
    return this.#toasts[toastKey] ?? null;
  }

  updateToastMetadata(toastId: ToastId, updater: (metadata: ToastMetadata) => ToastMetadata) {
    const toast = this.getToastById(toastId);
    if (!toast) { throw new Error(`Missing toast: ${toastId}`); }

    this.#toasts = {
      ...this.#toasts,
      [this.keyFromId(toastId)]: { ...toast, metadata: updater(toast.metadata) },
    };
  }

  // Returns true if the toast has a dedupeKey and it already exists in the set,
  // indicating that a duplicate toast should be suppressed.
  hasActiveDedupeKey(toast: ToastDescriptor) {
    return typeof toast.options?.dedupeKey !== 'undefined'
      ? this.#dedupeKeys.has(toast.options.dedupeKey)
      : false;
  }

  addDedupeKey(toast: ToastWithMetadata) {
    const dedupeKey = toast.descriptor.options?.dedupeKey;

    if (typeof dedupeKey !== 'undefined') {
      this.#dedupeKeys.add(dedupeKey);
    }
  }

  deleteDedupeKey(toast: ToastWithMetadata) {
    const dedupeKey = toast.descriptor.options?.dedupeKey;

    if (typeof dedupeKey !== 'undefined') {
      this.#dedupeKeys.delete(dedupeKey);
    }
  }

  dismissToast(toastId: ToastId) {
    const toastKey = this.keyFromId(toastId);
    const toast = this.getToastById(toastId);
    if (!toast) { return; } // If the toast doesn't exist (anymore), ignore

    // Note: make sure to do an immutable update, otherwise this may not cause a rerender downstream
    if (typeof toast !== 'undefined') {
      this.updateToastMetadata(toastId, metadata => ({ ...metadata, dismissed: true }));
      this.publish();
    }

    // Clean up garbage data after the exit animation has had a chance to complete
    window.setTimeout(() => {
      const toasts = { ...this.#toasts };
      delete toasts[toastKey];
      this.deleteDedupeKey(toast);
      this.#toasts = toasts;
      this.publish();
    }, this.#options.exitAnimationDelay);
  }

  dismissAllToasts() {
    for (const toastKey of Object.keys(this.#toasts)) {
      this.dismissToast(this.idFromKey(toastKey));
    }
  }

  scheduleClose(toastId: ToastId, closeDelay: number /*ms*/): Timer {
    return new Timer(() => { this.dismissToast(toastId); }, closeDelay);
  }

  announceToast(toastId: ToastId, toast: ToastDescriptor) {
    const toastKey = this.keyFromId(toastId);

    // Note: make sure to do an immutable update, otherwise this may not cause a rerender downstream
    const toasts = { ...this.#toasts };

    // Replace (and refresh) any existing toast with the same ID
    if (Object.hasOwn(this.#toasts, toastId)) {
      delete toasts[toastKey];
    }

    // Schedule autoclose, if configured
    let autoCloseTimer: null | Timer = null;
    const autoCloseDelay: false | number = toast.options?.autoClose ?? this.#options.autoCloseDelay;
    if (autoCloseDelay && autoCloseDelay > 0) {
      const autoCloseDelayMax = Math.max(autoCloseDelay, this.#options.entryAnimationDelay);
      autoCloseTimer = this.scheduleClose(toastId, autoCloseDelayMax);
    }

    // Add the new toast
    toasts[toastKey] = {
      metadata: { openedAt: new Date(), dismissed: false, autoCloseTimer },
      descriptor: toast,
    };

    this.addDedupeKey(toasts[toastKey]);
    this.#toasts = toasts;
    this.publish();
  }

  shouldSkipEntryAnimation(toastId: ToastId) {
    const toastKey = this.keyFromId(toastId);
    const toast = this.#toasts[toastKey];
    if (typeof toast === 'undefined') { return; }

    const isDismissed = toast.metadata.dismissed;
    const openedAt: Date = toast.metadata.openedAt;
    return !isDismissed && (Date.now() - openedAt.valueOf()) >= this.#options.entryAnimationDelay;
  }

  pauseAutoClose(toastId: ToastId) {
    const toastKey = this.keyFromId(toastId);
    const toast = this.#toasts[toastKey];
    if (typeof toast === 'undefined') { return; }

    const autoCloseTimer = toast.metadata.autoCloseTimer;
    autoCloseTimer?.pause(); // Pause the auto-close timer, if any
  }

  resumeAutoClose(toastId: ToastId) {
    const toastKey = this.keyFromId(toastId);
    const toast = this.#toasts[toastKey];
    if (typeof toast === 'undefined') { return; }

    const autoCloseTimer = toast.metadata.autoCloseTimer;
    autoCloseTimer?.resume(); // Resume the auto-close timer, if any
  }

  onPageVisible() {
    for (const toastKey of Object.keys(this.#toasts)) {
      this.resumeAutoClose(this.idFromKey(toastKey));
    }
  }

  onPageHide() {
    for (const toastKey of Object.keys(this.#toasts)) {
      this.pauseAutoClose(this.idFromKey(toastKey));
    }
  }
}

