      ref,
      children,
      unstyled = false,
      size = 'medium',
      label,
      defaultSelected,
      selected = null,
      onSelect,
      disabled = false,
      name,
      placeholderEmpty = 'No items',
      form,
      inputProps,
      isLoading = false,
      virtualItemKeys = null,
      formatItemLabel,
      ...propsRest
